package com.supportsphere.model;
public abstract class User { private int userId; private String name,email,phone,area,city,landmark,status; private Role role; public User(){} public User(int id,String n,String e,String p,Role r,String a,String c,String l){userId=id;name=n;email=e;phone=p;role=r;area=a;city=c;landmark=l;} public abstract String getDashboardType(); public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getArea(){return area;} public void setArea(String v){area=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getLandmark(){return landmark;} public void setLandmark(String v){landmark=v;} public String getLocationLabel(){return (area==null?"":area)+(city==null||city.isBlank()?"":", "+city);} }
